# GCU launch limits (grid.x <= 65535, grid.y <= 255, grid.z <= 255): the
# dim-path kernels launch one program per BLOCK_M-row block, and
# cdiv(M, BLOCK_M) exceeds grid.x for large row counts (known cluster,
# e.g. the core benchmark shape (1024, 1024, 1024) with dim=-1 gives
# M = 1048576).  Row blocks are therefore spread over a 3-D grid.
_GRID_X_MAX = 65535
_GRID_Y_MAX = 255


def _row_block_grid(nprog):
    """Spread ``nprog`` logical row blocks over a 3-D grid within the GCU
    launch limits.  The kernels recompose the flat block id from the runtime
    grid shape via ``_flat_program_id()`` (``tle.num_programs``), so any
    decomposition with grid_x * grid_y * grid_z >= nprog is correct; blocks
    whose rows land beyond ``M`` are masked out by the in-kernel ``pid < M``
    guard.  For nprog <= 65535 the grid stays the original 1-D launch.
    """
    if nprog <= _GRID_X_MAX:
        return (nprog, 1, 1)
    grid_y = triton.cdiv(nprog, _GRID_X_MAX)
    if grid_y <= _GRID_Y_MAX:
        return (triton.cdiv(nprog, grid_y), grid_y, 1)
    grid_z = triton.cdiv(nprog, _GRID_X_MAX * _GRID_Y_MAX)
    grid_y = triton.cdiv(nprog, _GRID_X_MAX * grid_z)
    return (triton.cdiv(nprog, grid_y * grid_z), grid_y, grid_z)


def _row_grid(M):
    def grid(META):
        return _row_block_grid(triton.cdiv(M, META["BLOCK_M"]))

    return grid


@triton.jit
def _flat_program_id():
    return (
        tle.program_id(0)
        + tle.program_id(1) * tle.num_programs(0)
        + tle.program_id(2) * tle.num_programs(0) * tle.num_programs(1)
    )


