# Host-function policy (user ruling, 2026-11-12): the host may only allocate
# and launch this backend's own Triton kernels, never delegate the computation
# to aten.  The previous override routed everything through
# torch.ops.aten.norm.* to match the on-device reference bit-for-bit; that path
# is removed and the generic Triton kernels below are the implementation.
#
# Known non-quick caveat (kept from that override's analysis): with TO_CPU
# disabled the reference is aten::norm on a GCU fp32 tensor, which torch_gcu
# forwards to its CPU kernel; on the full suite's 24.6M-element reduction its
# fp32 accumulation order differs from this tree reduction by more than the
# 1.3e-6 rtol (4952.775391 vs the fp64 truth 4959.681350, where the tree
# reduction is the closer one).  That is a reference-order artifact, not a
# kernel defect, and the quick gate is unaffected.


def norm(x, p=2, dim=None, keepdim=False):
    logger.debug("GEMS NORM")
    dtype = x.dtype
    if dtype not in [torch.float16, torch.float32, torch.bfloat16]:
        raise NotImplementedError(f"norm not implemented for {dtype}")

    # Validate p value
    if p is not None and not isinstance(p, (int, float)):
        raise ValueError(f"norm: p must be a number, got {type(p)}")
    if isinstance(p, float) and math.isnan(p):
        raise ValueError("norm: p must not be NaN")

    with torch_device_fn.device(x.device):
        if dim is None:
            # Compute norm over all elements
            shape = [1] * x.ndim
            x = dim_compress(x, list(range(x.ndim)))
            M = x.numel()
            BLOCK_SIZE = triton.next_power_of_2(math.ceil(math.sqrt(M)))
            MID_SIZE = triton.cdiv(M, BLOCK_SIZE)
            BLOCK_MID = triton.next_power_of_2(MID_SIZE)

            mid = torch.empty([MID_SIZE], dtype=dtype, device=x.device)
            out = torch.empty(shape, dtype=dtype, device=x.device)
            if p == 2:
                l2_norm_kernel_1[(MID_SIZE,)](x, mid, M, BLOCK_SIZE)
                l2_norm_kernel_2[(1,)](mid, out, MID_SIZE, BLOCK_MID)
            elif p == float("inf"):
                max_norm_kernel_1[(MID_SIZE,)](x, mid, M, BLOCK_SIZE)
                max_norm_kernel_2[(1,)](mid, out, MID_SIZE, BLOCK_MID)
            elif p == -float("inf"):
                min_norm_kernel_1[(MID_SIZE,)](x, mid, M, BLOCK_SIZE)
                min_norm_kernel_2[(1,)](mid, out, MID_SIZE, BLOCK_MID)
            elif p == 0:
                l0_norm_kernel_1[(MID_SIZE,)](x, mid, M, BLOCK_SIZE)
                l0_norm_kernel_2[(1,)](mid, out, MID_SIZE, BLOCK_MID)
            else:
                l1_norm_kernel_1[(MID_SIZE,)](x, mid, p, M, BLOCK_SIZE)
                l1_norm_kernel_2[(1,)](mid, out, p, MID_SIZE, BLOCK_MID)
        else:
            shape = list(x.shape)
            # Handle negative dim
            if isinstance(dim, (list, tuple)):
                dim = [d % x.ndim for d in dim]
            else:
                dim = [dim % x.ndim]
            x = dim_compress(x, dim)
            N = 1
            for i in dim:
                N *= shape[i]
                shape[i] = 1
            M = x.numel() // N
            out = torch.empty(shape, dtype=dtype, device=x.device)
            grid = _row_grid(M)
            if p == 2:
                l2_norm_kernel[grid](x, out, M, N)
            elif p == float("inf"):
                max_norm_kernel[grid](x, out, M, N)
            elif p == -float("inf"):
                min_norm_kernel[grid](x, out, M, N)
            elif p == 0:
                l0_norm_kernel[grid](x, out, M, N)
            else:
                v_norm_kernel[grid](x, out, M, N, p)
    if not keepdim:
        out = out.squeeze() if dim is None else out.squeeze(dim=dim)
    return out


def norm_scalaropt_dim(x, p, dim, keepdim=False):
    logger.debug("GEMS NORM_SCALAR_OPT_DIM")
    return norm(x, p=p, dim=dim, keepdim=keepdim)


def norm_scalar(x, p=2):
    logger.debug("GEMS NORM_SCALAR")
    return norm(x, p=p, dim=None, keepdim=False)
